// Build step: embed the WasmGC module produced by `npm run build-wasm` into a
// TypeScript module as gzip+base64 (the cheminfo/inchi-js distribution pattern),
// and copy the TeaVM ESM runtime next to it. All outputs land in the gitignored
// `dist/` folder — they are regenerated by `npm run build`, never committed, and
// included in the published package via the `files` field in package.json.
import { copyFile, mkdir, readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { gzipSync } from 'node:zlib';

const root = join(import.meta.dirname, '..');
const wasmDir = join(root, 'java', 'target', 'wasm-gc');
const outDir = join(root, 'dist');

await mkdir(outDir, { recursive: true });

const wasm = await readFile(join(wasmDir, 'openchemlib.wasm'));
const gz = gzipSync(wasm, { level: 9 });
const base64 = gz.toString('base64');

await writeFile(
  join(outDir, 'data.ts'),
  `// Generated by build/embed-wasm.mjs — do not edit.\n/* eslint-disable */\nexport const wasmGzipBase64 =\n  '${base64}';\n`,
);
await copyFile(
  join(wasmDir, 'openchemlib.wasm-runtime.js'),
  join(outDir, 'runtime.js'),
);
// The runtime is generated JS; ship the hand-written type declaration alongside
// it so `import { load } from '../../dist/runtime.js'` is typed.
await copyFile(
  join(root, 'build', 'runtime.d.ts'),
  join(outDir, 'runtime.d.ts'),
);

// eslint-disable-next-line no-console
console.log(
  `embedded: wasm ${wasm.length} B -> gzip ${gz.length} B -> base64 ${base64.length} chars`,
);
